#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_ENTRIES 256
#define MAX_KEY_LEN 64
#define MAX_VAL_LEN 512

typedef struct {
    char key[MAX_KEY_LEN];
    char value[MAX_VAL_LEN];
    uint64_t timestamp;
    uint32_t flags;
} cache_entry_t;

typedef struct {
    cache_entry_t entries[MAX_ENTRIES];
    uint32_t head;
    uint32_t tail;
    uint32_t count;
    pthread_mutex_t lock;
    uint8_t initialized;
} secure_cache_t;

static secure_cache_t g_cache;

int cache_init(void) {
    memset(&g_cache, 0, sizeof(secure_cache_t));
    if (pthread_mutex_init(&g_cache.lock, NULL) != 0)
        return -1;
    g_cache.initialized = 1;
    return 0;
}

static int validate_key(const char *key, size_t key_len) {
    if (key == NULL || key_len == 0 || key_len >= MAX_KEY_LEN)
        return -1;
    for (size_t i = 0; i < key_len; i++) {
        if (key[i] == '\0') return -1;
        if ((unsigned char)key[i] < 0x20) return -1;
    }
    return 0;
}

static int validate_value(const char *value, size_t val_len) {
    if (value == NULL || val_len == 0 || val_len >= MAX_VAL_LEN)
        return -1;
    return 0;
}

static uint32_t next_index(uint32_t idx) {
    return (idx + 1) % MAX_ENTRIES;
}

int cache_put(const char *key, size_t key_len,
             const char *value, size_t val_len,
             uint64_t timestamp) {
    if (!g_cache.initialized) return -1;
    if (validate_key(key, key_len) != 0) return -1;
    if (validate_value(value, val_len) != 0) return -1;

    pthread_mutex_lock(&g_cache.lock);

    /* Check if key already exists - update in place */
    uint32_t idx = g_cache.tail;
    for (uint32_t i = 0; i < g_cache.count; i++) {
        if (strncmp(g_cache.entries[idx].key, key, MAX_KEY_LEN) == 0) {
            memcpy(g_cache.entries[idx].value, value, val_len);
            g_cache.entries[idx].value[val_len] = '\0';
            g_cache.entries[idx].timestamp = timestamp;
            pthread_mutex_unlock(&g_cache.lock);
            return 0;
        }
        idx = next_index(idx);
    }

    /* Evict oldest if full */
    if (g_cache.count >= MAX_ENTRIES) {
        g_cache.tail = next_index(g_cache.tail);
        g_cache.count--;
    }

    /* Insert at head */
    cache_entry_t *entry = &g_cache.entries[g_cache.head];
    memset(entry, 0, sizeof(cache_entry_t));
    memcpy(entry->key, key, key_len);
    entry->key[key_len] = '\0';
    memcpy(entry->value, value, val_len);
    entry->value[val_len] = '\0';
    entry->timestamp = timestamp;
    entry->flags = 0x01;

    g_cache.head = next_index(g_cache.head);
    g_cache.count++;

    pthread_mutex_unlock(&g_cache.lock);
    return 0;
}

int cache_get(const char *key, size_t key_len,
             char *output, size_t output_size,
             size_t *out_len) {
    if (!g_cache.initialized) return -1;
    if (validate_key(key, key_len) != 0) return -1;
    if (output == NULL || output_size == 0 || out_len == NULL) return -1;

    pthread_mutex_lock(&g_cache.lock);

    uint32_t idx = g_cache.tail;
    for (uint32_t i = 0; i < g_cache.count; i++) {
        if (strncmp(g_cache.entries[idx].key, key, MAX_KEY_LEN) == 0) {
            size_t vlen = strlen(g_cache.entries[idx].value);
            if (vlen >= output_size) {
                pthread_mutex_unlock(&g_cache.lock);
                return -2; /* buffer too small */
            }
            memcpy(output, g_cache.entries[idx].value, vlen + 1);
            *out_len = vlen;
            pthread_mutex_unlock(&g_cache.lock);
            return 0;
        }
        idx = next_index(idx);
    }

    pthread_mutex_unlock(&g_cache.lock);
    return -1; /* not found */
}

int cache_delete(const char *key, size_t key_len) {
    if (!g_cache.initialized) return -1;
    if (validate_key(key, key_len) != 0) return -1;

    pthread_mutex_lock(&g_cache.lock);

    uint32_t idx = g_cache.tail;
    for (uint32_t i = 0; i < g_cache.count; i++) {
        if (strncmp(g_cache.entries[idx].key, key, MAX_KEY_LEN) == 0) {
            /* Mark as deleted by zeroing key */
            memset(g_cache.entries[idx].key, 0, MAX_KEY_LEN);
            memset(g_cache.entries[idx].value, 0, MAX_VAL_LEN);
            g_cache.entries[idx].flags = 0;
            /* Don't adjust count - leave tombstone */
            pthread_mutex_unlock(&g_cache.lock);
            return 0;
        }
        idx = next_index(idx);
    }

    pthread_mutex_unlock(&g_cache.lock);
    return -1;
}

/* Bulk export: serialize all entries into caller buffer */
int cache_export(char *buffer, size_t buffer_size, size_t *written) {
    if (!g_cache.initialized) return -1;
    if (buffer == NULL || written == NULL) return -1;

    pthread_mutex_lock(&g_cache.lock);

    size_t offset = 0;
    uint32_t idx = g_cache.tail;

    for (uint32_t i = 0; i < g_cache.count; i++) {
        cache_entry_t *e = &g_cache.entries[idx];
        if (e->flags & 0x01) {
            size_t klen = strlen(e->key);
            size_t vlen = strlen(e->value);
            size_t entry_size = 4 + klen + 4 + vlen + 8; /* lengths + data + timestamp */

            if (offset + entry_size <= buffer_size) {
                uint32_t kl = (uint32_t)klen;
                uint32_t vl = (uint32_t)vlen;
                memcpy(buffer + offset, &kl, 4); offset += 4;
                memcpy(buffer + offset, e->key, klen); offset += klen;
                memcpy(buffer + offset, &vl, 4); offset += 4;
                memcpy(buffer + offset, e->value, vlen); offset += vlen;
                memcpy(buffer + offset, &e->timestamp, 8); offset += 8;
            } else {
                pthread_mutex_unlock(&g_cache.lock);
                *written = offset;
                return -2; /* buffer full */
            }
        }
        idx = next_index(idx);
    }

    *written = offset;
    pthread_mutex_unlock(&g_cache.lock);
    return 0;
}

/* Import entries from serialized buffer */
int cache_import(const char *buffer, size_t buffer_size, uint64_t base_timestamp) {
    if (!g_cache.initialized) return -1;
    if (buffer == NULL || buffer_size == 0) return -1;

    size_t offset = 0;

    while (offset < buffer_size) {
        if (buffer_size - offset < 4) return -1;
        uint32_t klen;
        memcpy(&klen, buffer + offset, 4);
        offset += 4;

        if (klen == 0 || klen >= MAX_KEY_LEN) return -1;
        if (buffer_size - offset < klen) return -1;
        const char *key = buffer + offset;
        offset += klen;

        if (buffer_size - offset < 4) return -1;
        uint32_t vlen;
        memcpy(&vlen, buffer + offset, 4);
        offset += 4;

        if (vlen == 0 || vlen >= MAX_VAL_LEN) return -1;
        if (buffer_size - offset < vlen) return -1;
        const char *value = buffer + offset;
        offset += vlen;

        if (buffer_size - offset < 8) return -1;
        uint64_t ts;
        memcpy(&ts, buffer + offset, 8);
        offset += 8;

        cache_put(key, klen, value, vlen, base_timestamp + ts);
    }

    return 0;
}
